# run_pool_sim.ps1 â€?milestone-5 regression: PH1P35 pool-based drs_iter,
# 2 DRS iterations, compare VS1/VS2 against the golden reference with check_drs.py.
#
# Requires Icarus Verilog (this machine: D:\iverilog\bin) and the golden data in
# rtl/data/kkt/full (generated by software/drs_reference.py gen full).
$ErrorActionPreference = "Stop"
$env:PATH = "D:\iverilog\bin;" + $env:PATH
$wt = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$s  = Join-Path $wt "rtl\solver"
Set-Location (Join-Path $wt "rtl\sim")

& iverilog -g2005 -o pool_sim.vvp `
  "$s\fp64.v" "$s\fp64_cmp.v" "$s\fp64_log.v" "$s\fp64_rsqrt.v" "$s\fp64_pool.v" `
  "$s\drs_iter.v" "$s\kkt_solve.v" "$s\banded_ldl_fp64_rb.v" "$s\spmv_fp64.v" `
  "$s\root_plus_pool.v" "$s\proj_soc_pool.v" "$s\proj_dual_cone_rb.v" "$s\s_build.v" `
  "$wt\rtl\sram64_ctrl.v" "$wt\rtl\flash_ctrl.v" "tb_drs_iter_2.v"
if ($LASTEXITCODE -ne 0) { throw "iverilog failed" }

& vvp pool_sim.vvp 2>&1 | Out-File -FilePath pool_sim_output.txt -Encoding ascii
$lines = Get-Content pool_sim_output.txt
$v1 = ($lines | Where-Object { $_ -match "^VS1:" }) -replace "^VS1:", "V1:"
$v2 = ($lines | Where-Object { $_ -match "^VS2:" }) -replace "^VS2:", "V2:"
Set-Content (Join-Path $wt "rtl\data\pool_sim_dump.txt") -Value @($v1, $v2) -Encoding ascii

$env:PYTHONPATH = $wt
& python (Join-Path $wt "software\check_drs.py") (Join-Path $wt "rtl\data\pool_sim_dump.txt")
